     * ServerSideRowModelApiModule`
     */
    fun getCacheBlockState(): JsAny
    /**
     * Returns `false` if grid allows for scrolling past the last row to load more rows, thus
     * providing infinite scroll. @agModule `InfiniteRowModelModule / ServerSideRowModelApiModule`
     */
    fun isLastRowIndexKnown(): Boolean?
}

external interface _StateGridApi {
    /**
     * Get the current state of the grid. Can be used in conjunction with the `initialState` grid
     * option or `api.setState()` to save and restore grid state. @agModule `GridStateModule`
     */
    fun getState(): GridState
    /**
     * Set the current state of the grid. Can be used in conjunction with `api.getState()` or
     * `onStateUpdated` to save and restore grid state. The provided state replaces the grid state
     * rather than patching it: every section it omits is reset unless listed in
     * `propertiesToIgnore`. @param propertiesToIgnore Top-level state sections to leave as they
     * are, e.g. `['filter']` keeps the current filters. @agModule `GridStateModule`
     */
    fun setState(state: GridState, propertiesToIgnore: Array<GridStateKey>?)
}

